import Foundation

/// The two sounds of a voice turn, his picks (2026-10-18): a short AI notification chime for
/// "listening" (its first three notes, 0.32 s) and the same chime lower and shorter for "done"
/// (0.17 s). From "Notification, positive" on Pixabay (Pixabay Content License: free to use in
/// apps, no attribution). 48 kHz mono 16-bit WAV, kept in code so the phone and the Mac client
/// (which builds these Voice sources) carry them without a resource bundle.
enum VoiceEarconSounds {
    static func data(for earcon: VoiceEarcon) -> Data {
        switch earcon {
        case .listening: return listening
        case .thinking: return done
        }
    }

